create table if not exists contacts(id uuid primary key default gen_random_uuid(),venue_id uuid not null references venues(id) on delete cascade,first_name text,last_name text,email text,phone text,created_at timestamptz not null default now());
create table if not exists enquiries(id uuid primary key default gen_random_uuid(),venue_id uuid not null references venues(id) on delete cascade,contact_id uuid references contacts(id) on delete set null,event_type text not null,event_date date,guest_count integer,estimated_value numeric(12,2),status text not null default 'new',source text,raw_message text,ai_score integer check(ai_score between 0 and 100),ai_summary text,next_action text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());